function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'MRUQueue' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with MRUQueue(n).';
  const n = args[0][0];
  if (!Number.isInteger(n) || n < 1 || n > 2000) return 'n is a whole number from 1 to 2000.';
  if (operations.length - 1 > 2000) return 'At most 2000 calls to fetch.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'fetch') return 'Only fetch can follow the constructor.';
    const a = args[i];
    if (!Array.isArray(a) || a.length !== 1 || !Number.isInteger(a[0]) || a[0] < 1 || a[0] > n) return 'fetch needs k from 1 to n.';
  }
  return null;
}

