class MRUQueue {
  constructor(n) {
    this.capacity = n + 2000;
    this.tree = new Array(this.capacity + 1).fill(0);
    this.values = new Array(this.capacity + 1).fill(0);
    this.size = 0;
    this.highBit = 1;
    while (this.highBit * 2 <= this.capacity) {
      this.highBit *= 2;
    }
    for (let value = 1; value <= n; value++) {
      this.append(value);
    }
  }

  add(index, delta) {
    for (let i = index; i <= this.capacity; i += i & -i) {
      this.tree[i] += delta;
    }
  }

  append(value) {
    this.size++;
    this.values[this.size] = value;
    this.add(this.size, 1);
  }

  findKth(k) {
    let position = 0;
    for (let step = this.highBit; step > 0; step >>= 1) {
      const next = position + step;
      if (next <= this.capacity && this.tree[next] < k) {
        position = next;
        k -= this.tree[next];
      }
    }
    return position + 1;
  }

  fetch(k) {
    const position = this.findKth(k);
    const value = this.values[position];
    this.add(position, -1);
    this.append(value);
    return value;
  }
}

