class MRUQueue {
  constructor(n) {
    this.queue = [];
    for (let i = 1; i <= n; i++) this.queue.push(i);
  }
  fetch(k) {
    const [value] = this.queue.splice(k - 1, 1);
    this.queue.push(value);
    return value;
  }
}

